@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class TenantFilter extends OncePerRequestFilter {
    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res,
                                    FilterChain chain) throws ServletException, IOException {
        String tenant = req.getHeader("X-Tenant-Id");
        TenantContext.set(tenant != null ? tenant : TenantContext.SHARED);  // luôn set, kể cả giá trị mặc định
        try {
            chain.doFilter(req, res);
        } finally {
            TenantContext.clear();   // chạy cả khi có exception
        }
    }
}

public final class TenantContext {
    public static final String SHARED = "shared";
    private static final ThreadLocal<String> CURRENT = new ThreadLocal<>();
    public static void set(String t) { CURRENT.set(t); }
    public static String get() {
        String t = CURRENT.get();
        // không có giá trị là lỗi lập trình, không âm thầm dùng "shared"
        if (t == null) throw new IllegalStateException("Tenant chưa được thiết lập");
        return t;
    }
    public static void clear() { CURRENT.remove(); }
}
